package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.RegraRepasseRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class RegraRepasseApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final RegraRepasseRepository repo; final OrganizacaoEclesialRepository org; public RegraRepasseApplicationService(RegraRepasseRepository r,OrganizacaoEclesialRepository o){repo=r;org=o;} @Transactional public RegraRepasse salvar(RegraRepasseRequest r){if(seguranca!=null)seguranca.validarAcesso(r.organizacaoOrigemUuid());var a=org.findByUuid(r.organizacaoOrigemUuid()).orElseThrow(()->new IllegalArgumentException("Organização de origem não encontrada."));var b=org.findByUuid(r.organizacaoDestinoUuid()).orElseThrow(()->new IllegalArgumentException("Organização de destino não encontrada."));if(!a.isAtivo()||!b.isAtivo())throw new IllegalArgumentException("As organizações do repasse devem estar ativas.");if(a.getId().equals(b.getId()))throw new IllegalArgumentException("Origem e destino devem ser diferentes.");if(r.dataFim()!=null&&r.dataFim().isBefore(r.dataInicio()))throw new IllegalArgumentException("Período inválido.");if(r.tipoBase()==TipoBaseRepasse.VALOR_FIXO&&(r.valorFixo()==null||r.percentual()!=null))throw new IllegalArgumentException("Regra de valor fixo deve informar apenas valor fixo.");if(r.tipoBase()!=TipoBaseRepasse.VALOR_FIXO&&(r.percentual()==null||r.valorFixo()!=null))throw new IllegalArgumentException("Regra percentual deve informar apenas percentual."); if(r.percentual()!=null&&(r.percentual().signum()<0||r.percentual().compareTo(new java.math.BigDecimal("100"))>0))throw new IllegalArgumentException("Percentual deve estar entre 0 e 100.");var e=new RegraRepasse();e.setOrganizacaoOrigemId(a.getId());e.setOrganizacaoDestinoId(b.getId());e.setTipoBase(r.tipoBase());e.setPercentual(r.percentual());e.setValorFixo(r.valorFixo());e.setPeriodicidade(r.periodicidade());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setAtivo(r.ativo()==null||r.ativo());e.setObservacao(r.observacao());return repo.save(e);} @Transactional(readOnly=true) public List<RegraRepasse> listar(){return repo.findAllByOrderByDataInicioDesc().stream().filter(e->{try{if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoOrigemId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).toList();}}